text:
 {
  "turns": [
    {
      "speaker": "agent",
      "text": "Thank you for calling Nimbus Telecom. My name is Arjun. How can I help you today?",
      "tags": [
        "greeting"
      ]
    },
    {
      "speaker": "customer",
      "text": "I am so sick of this! My internet has been dropping every ten minutes for the last three days. It is completely unusable!",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I am very sorry to hear that you are experiencing these drops. I know how frustrating it is when your connection is unstable.",
      "tags": [
        "empathy"
      ]
    },
    {
      "speaker": "agent",
      "text": "Before we look into the account, could you please provide your account number?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "My name is Karan Nair and my account number is 41055424.",
      "tags": [
        "identity_verification"
      ]
    },
    {
      "speaker": "agent",
      "text": "Thank you, Mr. Nair. I see your address is 239 MG Road. Is that correct?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Yes, that is correct. I just want this fixed now.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I have run a diagnostic on your line and it looks like there is a signal instability issue at the local exchange. I can see the drops in the logs.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Finally, someone sees it. I also need to pay my outstanding balance so it doesn't get cut off. My phone number is 96651 19718.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I can help with that. Please go ahead and provide the card details for the payment.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "It is four seven three seven five zero four three one zero three nine nine three one nine.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "The payment has been processed successfully. Now, regarding the network issue, I am going to raise a network ticket to have the exchange port reset and monitored.",
      "tags": [
        "action:technician_or_ticket"
      ]
    }
  ]
}
